def can_be_valid_by_inversion(s):
    balance = 0
    open_brackets = []

    # First pass to detect unmatched opening brackets
    for i, char in enumerate(s):
        if char == '(':
            open_brackets.append(i)
            balance += 1
        elif char == ')':
            if balance > 0:
                balance -= 1
            else:
                open_brackets.append(i)

    # If the sequence is already balanced, no inversion needed
    if balance == 0:
        return "possible"

    # If there's more than one unmatched opening bracket, inversion won't help
    if len(open_brackets) != 2 * balance:
        return "impossible"

    # Try inverting segments that could potentially fix the balance
    for i in range(len(open_brackets)):
        for j in range(i + 1, len(open_brackets)):
            inverted = list(s)
            for k in range(open_brackets[i], open_brackets[j] + 1):
                inverted[k] = '(' if s[k] == ')' else ')'
            new_s = ''.join(inverted)
            if is_balanced(new_s):
                return "possible"

    return "impossible"

